const MYSORE_PAINTING_INFO={id:"mysore-painting",title:"Mysore Painting",tagline:"Classical South Indian Art Form Celebrated for Delicate Linework & Pure Gold Gesso Embellishments",origin:"Mysore & Seringapatam, Karnataka, India",historicalPeriod:"Vijayanagara Empire (14th c.) to Wodeyar Dynasty (19th c.)",patrons:"Raja Wodeyar I, Mummadi Krishnaraja Wodeyar III",giStatus:"Geographical Indication (GI) Tagged (Handicrafts)",keyFeature:"Low-Relief Gold Gesso Work (Gacho Paste) & Delicate Brushwork",quickStats:[{label:"GI Tagged",value:"Karnataka Heritage",icon:"🎖️"},{label:"Gold Foil",value:"24-Karat Pure Vark",icon:"✨"},{label:"Embossing",value:"Subtle Low-Relief Gesso",icon:"🎨"},{label:"Masterwork",value:"Sritattvanidhi Text",icon:"📜"},{label:"Golden Era",value:"Wodeyar Patronage",icon:"👑"},{label:"Brushes",value:"Squirrel Hair Fine Tips",icon:"🖌️"}]},HISTORICAL_BACKGROUND={title:"Historical Origin & Wodeyar Legacy",subtitle:"From Vijayanagara royal courts to the golden era under Maharaja Krishnaraja Wodeyar III.",paragraphs:["Mysore Painting traces its origins to the 14th century Vijayanagara Empire. Following the battle of Talikota in 1565 CE, skilled artists of the Chitragara community migrated to Seringapatam (Srirangapatna) and Mysore under the royal patronage of Raja Wodeyar I (1578–1617 CE), laying the foundation of the distinct Mysore school of art.","The golden age of Mysore Painting arrived under Maharaja Mummadi Krishnaraja Wodeyar III (1794–1868 CE). A great patron of arts and literature, the Maharaja commissioned hundreds of paintings, murals on the walls of Jaganmohan Palace, and the monumental 9-volume iconographic treatise titled 'Sritattvanidhi', which standardized the iconography, colors, and postures of Hindu deities.","Mysore paintings are renowned for their elegance, muted colors, soft facial expressions, and sophisticated low-relief gold foil embossing. Unlike Tanjore paintings, which use heavy gesso with glass beads and precious stones, Mysore paintings feature delicate, subtle gesso work that gives the artwork a silky, understated grandeur."]},GOLD_WORK_STEPS=[{step:1,title:"Preparing the Gesso Paste (Gacho)",icon:"🥣",description:"Artists blend fine white lead (or zinc oxide), unboiled plaster of Paris (chalk powder), Arabic gum, and Gamboge tree resin to form a smooth, paste-like compound called Gacho."},{step:2,title:"Low-Relief Embossing",icon:"🖌️",description:"Using fine squirrel-hair brushes, the Gacho paste is painted onto selected areas—crowns (Mukuta), jewelry, archways (Prabhavali), thrones, and garment borders—to build a subtle raised relief."},{step:3,title:"Gilding 24K Gold Foil (Vark)",icon:"✨",description:"Thin leaves of pure 24-karat gold foil (Gold Vark) are carefully laid over the re-tackified gesso embossing and gently pressed down, adhering permanently to the raised relief."},{step:4,title:"Agate Stone Burnishing",icon:"💎",description:"The gold leaf is polished using a smooth agate stone tipped burnisher (Kalgutha). This burnishing process seals the gold, creating a mirror-like lustrous shine that never tarnishes over centuries."}],MATERIALS_CATALOG=[{name:"Base Board (Kardas)",category:"Canvas & Surface",description:"Cartridge paper or cotton cloth pasted onto seasoned teakwood boards or heavy paperboard, rubbed smooth with a quartz stone.",icon:"🖼️"},{name:"Squirrel Hair Brushes (Anjura)",category:"Drawing Tools",description:"Fine brushes handmade from squirrel tail hairs inserted into bird quills, allowing paper-thin line drawings and delicate facial detailing.",icon:"🖌️"},{name:"Tamarind Charcoal Sticks (Kitta)",category:"Drawing Tools",description:"Charred tamarind twigs used for drawing the preliminary light sketch before ink work.",icon:"✏️"},{name:"24-Karat Gold Leaf (Vark)",category:"Embellishment",description:"Pure gold hammered into tissue-thin foils, applied over gesso to signify divinity and royal radiance.",icon:"✨"},{name:"Gesso Compound (Gacho)",category:"Embossing Compound",description:"Mixture of white lead/zinc powder, Arabic gum, and Gamboge tree resin used for raised low-relief embellishments.",icon:"🧪"},{name:"Agate Stone Burnisher (Kalgutha)",category:"Polishing Tool",description:"Smooth agate stone tool used to rub and polish gold foil to achieve a brilliant metallic sheen.",icon:"💎"}],THEMES_LIST=[{title:"Sri Rama Pattabhisheka",category:"Epic & Mythological",description:"The coronation of Lord Rama alongside Sita, Lakshmana, Hanuman, and royal courtiers—one of the most celebrated master themes in Mysore art."},{title:"Divine Mother Goddesses",category:"Devotional Iconography",description:"Depictions of Goddess Sri Rajarajeshwari, Chamundeshwari, Lakshmi, and Saraswati adorned in opulent gold ornaments and intricate thrones."},{title:"Venugopala & Krishna Leela",category:"Devotional Iconography",description:"Lord Krishna playing the flute under flowering trees surrounded by gopis and cows, rendered in soft pastel shades."},{title:"Sritattvanidhi Iconography",category:"Classical Manuscripts",description:"Paintings strictly adhering to the 9-volume manuscript compiled by Krishnaraja Wodeyar III, depicting 32 forms of Ganesha, Shiva avatars, and celestial beings."},{title:"Wodeyar Royal Durbar & Portraits",category:"Royal & Historical",description:"Detailed royal portraits of Mysore Maharajas, Dasara processions, palace durbars, and court musicians."}],GALLERY_PAINTINGS=[{id:"rama-pattabhisheka",title:"Sri Rama Pattabhisheka",theme:"Epic & Mythological",period:"19th Century Wodeyar Era",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Rama_Pattabhisheka_Mysore_style.jpg/800px-Rama_Pattabhisheka_Mysore_style.jpg",description:"Grand coronation scene of Lord Rama and Sita on the golden throne, featuring elaborate Gesso gold work on crowns, archway, and robes."},{id:"rajarajeshwari",title:"Goddess Sri Rajarajeshwari",theme:"Devotional Iconography",period:"Classical Mysore School",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Rajarajeshwari_Mysore_Painting.jpg/800px-Rajarajeshwari_Mysore_Painting.jpg",description:"Enthroned Divine Mother holding sugarcane bow and lotus buds, surrounded by golden Prabhavali archway."},{id:"venugopala-krishna",title:"Venugopala Krishna",theme:"Devotional Iconography",period:"Late 18th Century",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Venugopala_Krishna_Mysore_Traditional.jpg/800px-Venugopala_Krishna_Mysore_Traditional.jpg",description:"Lord Krishna charming woodland creatures and gopis with his flute, featuring soft muted skin tones and burnished gold jewelry."},{id:"goddess-saraswati",title:"Goddess Saraswati",theme:"Devotional Iconography",period:"Sritattvanidhi Tradition",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Saraswati_Mysore_Traditional_Art.jpg/800px-Saraswati_Mysore_Traditional_Art.jpg",description:"Goddess of learning seated on a white swan with Veena, rendered with delicate lines and subtle gold foil highlights."},{id:"ganesha-32-forms",title:"Vidya Ganesha",theme:"Classical Manuscripts",period:"19th Century",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Ganesha_Mysore_Style_Painting.jpg/800px-Ganesha_Mysore_Style_Painting.jpg",description:"Lord Ganesha depicted according to Sritattvanidhi iconographic proportions, embellished with gold gesso ornaments."},{id:"kodandarama",title:"Kodandarama with Sita & Lakshmana",theme:"Epic & Mythological",period:"Mysore Royal School",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Kodandarama_Mysore_Painting.jpg/800px-Kodandarama_Mysore_Painting.jpg",description:"Lord Rama holding his divine bow Kodanda alongside Sita, Lakshmana, and devotionally kneeling Hanuman."}],REFERENCES_LIST=[{title:"Sritattvanidhi Treatise",type:"Historical Manuscript",description:"9-volume iconographic treatise compiled under Maharaja Mummadi Krishnaraja Wodeyar III (1794–1868 CE), defining Mysore painting iconography."},{title:"Jaganmohan Palace Art Gallery",type:"Museum & Gallery",description:"Located in Mysore, holding the world's largest collection of original Mysore traditional paintings, royal portraits, and murals."},{title:"Geographical Indication (GI) Tag",type:"Intellectual Property Protection",description:"Official GI Tag registration under Handicrafts (GI Application No. 132), protecting the traditional Mysore Painting technique."},{title:"Crafts Council of Karnataka",type:"Art Preservation Body",description:"Organization dedicated to training hereditary and modern artists in authentic Gacho gesso gold leaf preparation and squirrel-brush technique."}];"undefined"!=typeof module&&module.exports&&(module.exports={MYSORE_PAINTING_INFO:MYSORE_PAINTING_INFO,HISTORICAL_BACKGROUND:HISTORICAL_BACKGROUND,GOLD_WORK_STEPS:GOLD_WORK_STEPS,MATERIALS_CATALOG:MATERIALS_CATALOG,THEMES_LIST:THEMES_LIST,GALLERY_PAINTINGS:GALLERY_PAINTINGS,REFERENCES_LIST:REFERENCES_LIST});